  "description": "Output from the external research task (Tavily + CompetitiveIntel).\n\nContains market sizing and competitive landscape data. No customer\nevidence or internal context; those come from separate tasks.",
  "properties": {
    "market_sizing": {
      "properties": {
        "summary": {
          "title": "Summary",
          "type": "string"
        },
        "data_points": {
          "description": "Each a specific stat with source attribution",
          "items": {
            "type": "string"
          },
          "title": "Data Points",
          "type": "array"
        },
        "sources": {
          "items": {
            "type": "string"
          },
          "title": "Sources",
          "type": "array"
        }
      },
      "required": [
        "summary",
        "data_points",
        "sources"
      ],
      "title": "MarketSizing",
      "type": "object",
      "additionalProperties": false
    },
    "competitors": {
      "description": "3-5 competitors with review data, pros, cons, pricing",
      "items": {
        "properties": {
          "name": {
            "title": "Name",
            "type": "string"
          },
          "description": {
            "title": "Description",
            "type": "string"
          },
          "strengths": {
            "items": {
              "type": "string"
            },
            "title": "Strengths",
            "type": "array"
          },
          "weaknesses": {
            "items": {
              "type": "string"
            },
            "title": "Weaknesses",
            "type": "array"
          },
          "relevance": {
            "description": "Why this competitor matters to the PM's problem",
            "title": "Relevance",
            "type": "string"
          },
          "review_data": {
            "description": "Ratings from G2, Capterra, TrustRadius",
            "items": {
              "properties": {
                "platform": {
                  "description": "G2, Capterra, or TrustRadius",
                  "title": "Platform",
                  "type": "string"
                },
                "rating": {
                  "description": "e.g., 4.7/5",
                  "title": "Rating",
                  "type": "string"
                },
                "review_count": {
                  "default": "",
                  "description": "e.g., 5,200+",
                  "title": "Review Count",
                  "type": "string"
                },
                "source_url": {
                  "default": "",
                  "description": "Link to the review page if available",
                  "title": "Source Url",
                  "type": "string"
                }
              },
              "required": [
                "platform",
                "rating",
                "review_count",
                "source_url"
              ],
              "title": "ReviewData",
              "type": "object",
              "additionalProperties": false
            },
            "title": "Review Data",
            "type": "array"
          },
          "top_pros": {
            "description": "Recurring positive themes from user reviews",
            "items": {
              "type": "string"
            },
            "title": "Top Pros",
            "type": "array"
          },
          "top_cons": {
            "description": "Recurring negative themes / complaints from user reviews",
            "items": {
              "type": "string"
            },
            "title": "Top Cons",
            "type": "array"
          },
          "reviewer_roles": {
            "description": "Common roles of reviewers (e.g., Product Manager, Software Engineer)",
            "items": {
              "type": "string"
            },
            "title": "Reviewer Roles",
            "type": "array"
          },
          "pricing_summary": {
            "default": "",
            "description": "Pricing tier info if available from review platforms",
            "title": "Pricing Summary",
            "type": "string"
          }
        },
        "required": [
          "name",
          "description",
          "strengths",
          "weaknesses",
          "relevance",
          "review_data",
          "top_pros",
          "top_cons",
          "reviewer_roles",
          "pricing_summary"
        ],
        "title": "CompetitorAnalysis",
        "type": "object",
        "additionalProperties": false
      },
      "title": "Competitors",
      "type": "array"
    },
    "external_sources": {
      "description": "All external sources cited in this output",
      "items": {
        "type": "string"
      },
      "title": "External Sources",
      "type": "array"
    },
    "external_gaps": {
      "description": "Topics where external research found no data",
      "items": {
        "type": "string"
      },
      "title": "External Gaps",
      "type": "array"
    },
    "internal_findings": {
      "description": "Findings from internal Amazon systems (wiki, code search, Taskei, Quip)",
      "items": {
        "type": "string"
      },
      "title": "Internal Findings",
      "type": "array"
    }
  },
  "required": [
    "market_sizing",
    "competitors",
    "external_sources",
    "external_gaps",
    "internal_findings"
  ],
  "title": "ExternalResearchOutput",
  "type": "object",
  "additionalProperties": false
}

